900	
901	int64_t llama_moe_cache::copy_experts(ggml_backend_t backend, const ggml_tensor * w, ggml_tensor * dst, int64_t e, int64_t last) {
902	    return pimpl->copy_experts(backend, w, dst, e, last);

370	    int32_t n_expert_used;
371	
372	    stats stats_small; // up to 8 tokens per ubatch
373	    stats stats_large;
374	    stats stats_copy;  // experts copied from the cache for large batches
375	
376	    std::vector<device> devices;
377	    std::vector<group> groups;
378	    std::vector<layer> layers;
379	    std::unordered_map<const ggml_tensor *, binding> bindings; // host experts -> cached experts
380	    std::unordered_map<const ggml_tensor *, std::pair<int32_t, bool>> layer_of; // slot map -> layer, and if the graph that looks it up has a CPU part
381	
382	    std::vector<int32_t> ids;
383	    std::vector<moe_cache_lru::fill> fills;
384	    std::vector<moe_cache_lru::fill> cpu;
385	
386	    float    cpu_share = 0.0f;
387	    uint32_t cpu_share_q = 0; // cpu_share in 1/65536, integer so that a simulator can reproduce the rounding
388	    int32_t  n_zero    = 0; // zero slots per group
389	
390	    // LLAMA_MOE_CACHE_TRACE: the selected experts of each slot lookup, for a simulator of the cache
391	    FILE * trace = nullptr;
392	
393	    // slot maps in host memory
394	    ggml_context_ptr ctx_host;
395	    ggml_backend_buffer_ptr buf_host;
396	    size_t buf_host_size = 0;
397	
398	    // views used by copy_experts
399	    ggml_context_ptr ctx_views;
400	
401	    impl(const llama_model & model, bool no_alloc, const std::vector<ggml_backend_t> & backends, const std::vector<ggml_backend_buffer_type_t> & bufts, size_t size, float cpu_share) :
402	            n_expert_used(model.hparams.n_expert_used_max()), layers(model.layers.size()), cpu_share(std::clamp(cpu_share, 0.0f, 1.0f)) {
403	        for (size_t i = 0; i < backends.size(); ++i) {
404	            const auto dev_type = ggml_backend_dev_type(ggml_backend_get_device(backends[i]));
405	            if (dev_type == GGML_BACKEND_DEVICE_TYPE_GPU || dev_type == GGML_BACKEND_DEVICE_TYPE_IGPU) {
406	                auto & d = devices.emplace_back();
407	                d.backend = backends[i];
408	                d.buft    = bufts[i];
409	            }
410	        }
411	        if (devices.empty()) {
412	            throw std::runtime_error("MoE cache requires a GPU backend");
413	        }
414	        if (model.split_mode() == LLAMA_SPLIT_MODE_TENSOR) {
415	            throw std::runtime_error("MoE cache does not support tensor parallelism");
416	        }
417	        if (model.hparams.n_expert == 0 || n_expert_used == 0) {
418	            throw std::runtime_error("MoE cache requires a MoE model");
419	        }
420	
421	        // only cache layers that keep all of their experts in host memory, on the device the layer is assigned to
422	        for (size_t il = 0; il < model.layers.size(); ++il) {
423	            auto experts = llama_moe_cache_layer_experts(model.layers[il]);
424	            if (experts.empty() || !std::all_of(experts.begin(), experts.end(), llama_moe_cache_is_host_weight)) {
425	                continue;
426	            }
427	            const auto it_dev = std::find_if(devices.begin(), devices.end(), [&](const device & d) { return ggml_backend_get_device(d.backend) == model.dev_layer(il); });
428	            if (it_dev == devices.end()) {
429	                continue;
430	            }
431	            const int32_t id = (int32_t) (it_dev - devices.begin());
432	            auto it = std::find_if(groups.begin(), groups.end(), [&](const group & g) { return g.id == id && llama_moe_cache_same_layout(g.ref, experts); });
433	            if (it == groups.end()) {
434	                groups.emplace_back();
435	                it = groups.end() - 1;
436	                it->id  = id;
437	                it->ref = experts;
438	            }
439	            it->layers.push_back(il);
440	            for (const ggml_tensor * t : experts) {
441	                it->host_bytes         += ggml_nbytes(t);
442	                devices[id].host_bytes += ggml_nbytes(t);
443	            }
444	        }
445	        if (groups.empty()) {
446	            LLAMA_LOG_WARN("%s: no layer has all of its experts in host memory, MoE cache is disabled\n", __func__);
447	            return;
448	        }
449	
450	        // with misses on the CPU, the n_zero slots after the cached ones stay zero: the device computes these misses as zero
451	        // one extra slot at the end, CUDA MMQ can read past the last expert
452	        n_zero = cpu_share > 0.0f ? std::min<int32_t>(n_expert_used, 64) : 0;
453	        auto alloc_size = [&](const group & g, int32_t n_slots) {
454	            const size_t alignment = ggml_backend_buft_get_alignment(devices[g.id].buft);
455	            size_t res = 0;
456	            for (const ggml_tensor * t : g.ref) {
457	                res += GGML_PAD(t->nb[2]*(n_slots + n_zero + 1), alignment);
458	            }
459	            return res;
460	        };
461	
462	        // the budget is split among the devices with host experts like the layers, by the tensor split or by default by free memory
463	        const float * tensor_split = model.tensor_split();
464	        const bool split_by_free = tensor_split == nullptr ||
465	            std::all_of(tensor_split, tensor_split + model.n_devices(), [](float x) { return x == 0.0f; });
466	        double split_sum = 0.0;
467	        for (device & d : devices) {
468	            if (d.host_bytes == 0) {
469	                continue;
470	            }
471	            ggml_backend_dev_t dev = ggml_backend_get_device(d.backend);
472	            if (split_by_free) {
473	                size_t free;
474	                size_t total;
475	                ggml_backend_dev_memory(dev, &free, &total);
476	                d.split = (double) free;
477	            } else {
478	                const auto it = std::find_if(model.devices.begin(), model.devices.end(), [&](const llama_device & ld) { return ld.dev == dev; });
479	                GGML_ASSERT(it != model.devices.end());
480	                d.split = (double) tensor_split[it - model.devices.begin()];
481	            }
482	            split_sum += d.split;
483	        }
484	        if (split_sum == 0.0) {
485	            // the devices do not report their free memory
486	            for (device & d : devices) {
487	                d.split    = d.host_bytes > 0 ? 1.0 : 0.0;
488	                split_sum += d.split;
489	            }
490	        }
491	
492	        // within a device the budget is split by the size of the experts, so each group caches the same fraction of its experts
493	        cpu_share_q = (uint32_t) std::lround(cpu_share*65536.0f);
494	        if (const char * path = getenv("LLAMA_MOE_CACHE_TRACE"); path != nullptr && *path != '\0') {
495	            trace = fopen(path, "wb");
496	            if (trace == nullptr) {
497	                throw std::runtime_error(std::string("failed to open the MoE cache trace ") + path);
498	            }
499	            write_trace_header(split_sum);
500	        }
501	        std::vector<size_t> n_tensors(devices.size(), 0);
502	        size_t n_tensors_host = 0;
503	        for (group & g : groups) {
504	            const device & d = devices[g.id];
505	            const int32_t n_expert  = g.ref[0]->ne[2];
506	            const size_t  budget    = (size_t) ((double) size*d.split/split_sum*g.host_bytes/d.host_bytes);
507	            const int32_t max_slots = g.layers.size()*n_expert;
508	            while (g.n_slots < max_slots && alloc_size(g, g.n_slots + 1) <= budget) {
509	                g.n_slots++;
510	            }
511	            if (g.n_slots < n_expert_used) {
512	                LLAMA_LOG_WARN("%s: MoE cache budget is too small for %zu layers, they are not cached\n", __func__, g.layers.size());
513	                g.n_slots = 0;
514	                continue;
515	            }
516	            g.lru.init(model.layers.size(), n_expert, g.n_slots);
517	            n_tensors[g.id] += g.ref.size()*(1 + g.layers.size());
518	            n_tensors_host  += g.layers.size()*(n_zero > 0 ? 3 : 1); // slot maps and CPU map
519	        }
520	        if (n_tensors_host == 0) {
521	            throw std::runtime_error("MoE cache is too small to hold the experts of one token");
522	        }
523	
524	        auto init_ctx = [](size_t n_tensors) {
525	            ggml_init_params params = {
526	                /*.mem_size   =*/ n_tensors*ggml_tensor_overhead(),
527	                /*.mem_buffer =*/ nullptr,
528	                /*.no_alloc   =*/ true,
529	            };
530	            ggml_context_ptr res(ggml_init(params));
531	            if (!res) {
532	                throw std::runtime_error("failed to create the MoE cache context");
533	            }
534	            return res;
535	        };
536	        for (size_t id = 0; id < devices.size(); ++id) {
537	            if (n_tensors[id] > 0) {
538	                devices[id].ctx = init_ctx(n_tensors[id]);
539	            }
540	        }
541	        ctx_host  = init_ctx(n_tensors_host);
542	        ctx_views = init_ctx(2);
543	
544	        ggml_backend_buffer_type_t buft_host = ggml_backend_cpu_buffer_type();
545	        const size_t alignment_host = ggml_backend_buft_get_alignment(buft_host);
546	
547	        for (size_t ig = 0; ig < groups.size(); ++ig) {
548	            group & g = groups[ig];
549	            if (g.n_slots == 0) {
550	                continue;
551	            }
552	            ggml_context * ctx = devices[g.id].ctx.get();
553	            for (const ggml_tensor * t : g.ref) {
554	                ggml_tensor * bank = ggml_new_tensor_3d(ctx, t->type, t->ne[0], t->ne[1], g.n_slots + n_zero + 1);
555	                GGML_ASSERT(bank->nb[2] == t->nb[2]);
556	                ggml_format_name(bank, "moe_cache.%zu.%s", ig, t->name);
557	                g.banks.push_back(bank);
558	            }
559	            for (int32_t il : g.layers) {
560	                layer & l = layers[il];
561	                l.ig      = (int32_t) ig;
562	                l.experts = llama_moe_cache_layer_experts(model.layers[il]);
563	                for (size_t ip = 0; ip < l.experts.size(); ++ip) {
564	                    ggml_tensor * bank   = g.banks[ip];
565	                    ggml_tensor * cached = ggml_view_3d(ctx, bank, bank->ne[0], bank->ne[1], g.n_slots + n_zero, bank->nb[1], bank->nb[2], 0);
566	                    ggml_format_name(cached, "moe_cache.%s", l.experts[ip]->name);
567	                    bindings[l.experts[ip]] = { il, (int32_t) ip, cached };
568	                }
569	                l.slot_map = ggml_new_tensor_2d(ctx_host.get(), GGML_TYPE_I32, 1, g.ref[0]->ne[2]);
570	                ggml_format_name(l.slot_map, "moe_cache.slot_map-%d", il);
571	                layer_of[l.slot_map] = { il, false };
572	                buf_host_size += GGML_PAD(ggml_nbytes(l.slot_map), alignment_host);
573	                if (n_zero > 0) {
574	                    l.slot_map_cpu = ggml_new_tensor_2d(ctx_host.get(), GGML_TYPE_I32, 1, g.ref[0]->ne[2]);
575	                    ggml_format_name(l.slot_map_cpu, "moe_cache.slot_map_cpu-%d", il);
576	                    layer_of[l.slot_map_cpu] = { il, true };
577	                    buf_host_size += GGML_PAD(ggml_nbytes(l.slot_map_cpu), alignment_host);
578	                    l.cpu_map = ggml_new_tensor_2d(ctx_host.get(), GGML_TYPE_I32, 1, g.ref[0]->ne[2]);
579	                    ggml_format_name(l.cpu_map, "moe_cache.cpu_map-%d", il);
580	                    buf_host_size += GGML_PAD(ggml_nbytes(l.cpu_map), alignment_host);
581	                }
582	            }
583	            devices[g.id].buf_size += alloc_size(g, g.n_slots);
584	        }
585	
586	        // with no_alloc, dummy buffers are attached so the memory use can still be measured, see llama_context::memory_breakdown
587	        for (device & d : devices) {
588	            if (!d.ctx) {
589	                continue;
590	            }
591	            d.buf = llama_memory_bufs::alloc_buf(d.ctx.get(), d.buft, no_alloc, "MoE cache");
592	            if (!no_alloc) {
593	                ggml_backend_buffer_clear(d.buf.get(), 0);
594	                d.buf_size = ggml_backend_buffer_get_size(d.buf.get());
595	            }
596	        }
597	        buf_host = llama_memory_bufs::alloc_buf(ctx_host.get(), buft_host, no_alloc, "MoE cache slot maps");
598	        if (!no_alloc) {
599	            ggml_backend_buffer_clear(buf_host.get(), 0xff); // the CPU maps are -1
600	            buf_host_size = ggml_backend_buffer_get_size(buf_host.get());
601	
602	            for (group & g : groups) {
603	                for (int32_t il : g.layers) {
604	                    if (layers[il].slot_map != nullptr) {
605	                        int32_t * slots = (int32_t *) layers[il].slot_map->data;
606	                        std::fill(slots, slots + layers[il].slot_map->ne[1], g.lru.empty);
607	                        g.lru.slot_map[il] = slots;
608	                    }
609	                }
610	            }
611	        }
612	
613	        // as weights, the ops that read the banks run on the device and the slot maps are copied with the copy callback
614	        for (device & d : devices) {
615	            if (d.buf) {
616	                ggml_backend_buffer_set_usage(d.buf.get(), GGML_BACKEND_BUFFER_USAGE_WEIGHTS);
617	            }
618	        }
619	        ggml_backend_buffer_set_usage(buf_host.get(), GGML_BACKEND_BUFFER_USAGE_WEIGHTS);
620	
621	        for (size_t id = 0; id < devices.size(); ++id) {
622	            const device & d = devices[id];
623	            if (d.host_bytes == 0) {
624	                continue;
625	            }
626	            LLAMA_LOG_INFO("%s: %10s MoE cache size = %8.2f MiB for %.2f MiB of host experts, %.0f%% of the misses on the CPU\n", __func__,
627	                ggml_backend_buft_name(d.buft), d.buf_size/1024.0/1024.0, d.host_bytes/1024.0/1024.0, 100.0*cpu_share);
628	            for (const group & g : groups) {
629	                if (g.id == (int32_t) id) {
630	                    LLAMA_LOG_INFO("%s: %2zu layers, %s: %5d slots (%.1f%%, %.1f tokens worth)\n", __func__,
631	                        g.layers.size(), ggml_type_name(g.ref.back()->type), g.n_slots, 100.0*g.n_slots/(g.layers.size()*g.ref[0]->ne[2]),
632	                        (double) g.n_slots/(g.layers.size()*n_expert_used));
633	                }
634	            }
635	        }
636	    }
637	
638	    ggml_backend_t backend(int32_t il) const {
639	        return devices[groups[layers[il].ig].id].backend;
640	    }
641	
642	    // trace format, little endian: "MCT1", then u32 n_layer, n_expert_used, n_group
643	    // per group: u32 device, n_expert, n_layers, the layers (u32), f64 split, split_sum, u64 group host bytes, device host bytes, alignment,
644	    //            u32 n_tensors, the bytes of one expert of each tensor (u64)
645	    // then one record per slot lookup: i32 layer, experts per token, n_ids, the ids (i32)
646	    void write_trace_header(double split_sum) {
647	        auto u32 = [&](uint32_t v) { fwrite(&v, sizeof(v), 1, trace); };
648	        auto u64 = [&](uint64_t v) { fwrite(&v, sizeof(v), 1, trace); };
649	        auto f64 = [&](double   v) { fwrite(&v, sizeof(v), 1, trace); };
650	        fwrite("MCT1", 1, 4, trace);
651	        u32(layers.size());
652	        u32(n_expert_used);
653	        u32(groups.size());
654	        for (const group & g : groups) {
655	            const device & d = devices[g.id];
656	            u32(g.id);
657	            u32(g.ref[0]->ne[2]);
658	            u32(g.layers.size());
659	            for (int32_t il : g.layers) {
660	                u32(il);
661	            }
662	            f64(d.split);
663	            f64(split_sum);
664	            u64(g.host_bytes);
665	            u64(d.host_bytes);
666	            u64(ggml_backend_buft_get_alignment(d.buft));
667	            u32(g.ref.size());
668	            for (const ggml_tensor * t : g.ref) {
669	                u64(t->nb[2]);
670	            }
671	        }
672	    }
673	
674	    void write_trace(int32_t il, int32_t n_used) {
675	        const int32_t rec[3] = { il, n_used, (int32_t) ids.size() };
676	        fwrite(rec, sizeof(int32_t), 3, trace);
677	        fwrite(ids.data(), sizeof(int32_t), ids.size(), trace);
678	    }
679	
680	    ~impl() {
681	        log_stats();
682	        if (trace != nullptr) {
683	            fclose(trace);
684	        }
685	    }
686	
687	    ggml_tensor * get_slot_map(int32_t il, int64_t n_tokens, int64_t n_expert_used, bool cpu_part) const {
688	        if (il < 0 || il >= (int32_t) layers.size() || layers[il].ig < 0) {
689	            return nullptr;
690	        }
691	        const layer & l = layers[il];
692	
693	        // large batches use most experts of a layer, so they gain little from the cache and would evict the experts used in generation
694	        if (n_tokens == 0 || n_tokens > max_batch || std::min(n_tokens*n_expert_used, l.slot_map->ne[1]) > groups[l.ig].n_slots) {
695	            return nullptr;
696	        }
697	        GGML_ASSERT(!cpu_part || l.slot_map_cpu != nullptr);
698	        return cpu_part ? l.slot_map_cpu : l.slot_map;
699	    }
700	
701	    ggml_tensor * get_cpu_map(int32_t il, int64_t n_tokens) const {
702	        if (il < 0 || il >= (int32_t) layers.size() || layers[il].cpu_map == nullptr) {
703	            return nullptr;
704	        }
705	        // the scheduler would run the CPU part on a device that offloads such batches from host weights
706	        ggml_tensor probe = {};
707	        probe.op    = GGML_OP_MUL_MAT_ID;
708	        probe.type  = GGML_TYPE_F32;
709	        probe.ne[0] = 1;
710	        probe.ne[1] = n_expert_used;
711	        probe.ne[2] = n_tokens;
712	        probe.ne[3] = 1;
713	        for (const device & d : devices) {
714	            if (ggml_backend_offload_op(d.backend, &probe)) {
715	                return nullptr;
716	            }
717	        }
718	        return layers[il].cpu_map;
719	    }
720	
721	    ggml_tensor * get_experts(const ggml_tensor * w) const {
722	        const auto it = bindings.find(w);
723	        return it != bindings.end() ? it->second.cached : nullptr;
724	    }
725	
726	    int64_t copy_experts(ggml_backend_t backend, const ggml_tensor * w, ggml_tensor * dst, int64_t e, int64_t last) {
727	        const auto it = bindings.find(w);
728	        if (it == bindings.end()) {
729	            return 0;
730	        }
731	        const binding & b = it->second;
732	        const group & g = groups[layers[b.il].ig];
733	        if (backend != devices[g.id].backend) {
734	            return 0;
735	        }
736	
737	        // large batches only read the cache, so the experts used in generation stay in it
738	        const int32_t * slots = g.lru.slot_map[b.il];
739	        if (slots == nullptr || slots[e] >= g.n_slots) {
740	            return 0;
741	        }
742	        int64_t n = 1;
743	        while (e + n <= last && slots[e + n] < g.n_slots && slots[e + n] == slots[e] + n) {
744	            n++;
745	        }
746	
747	        ggml_tensor * bank = g.banks[b.ip];
748	        ggml_reset(ctx_views.get());
749	        ggml_tensor * src_view = ggml_view_3d(ctx_views.get(), bank, bank->ne[0], bank->ne[1], n, bank->nb[1], bank->nb[2], slots[e]*bank->nb[2]);
750	        ggml_tensor * dst_view = ggml_view_3d(ctx_views.get(), dst,  dst->ne[0],  dst->ne[1],  n, dst->nb[1],  dst->nb[2],  e*dst->nb[2]);
751	        ggml_backend_view_init(src_view);
752	        ggml_backend_view_init(dst_view);
753	        ggml_backend_tensor_copy_async(backend, backend, src_view, dst_view);
754	
755	        stats_copy.hits  += n;
756	        stats_copy.bytes += ggml_nbytes(src_view);
757	
758	        return n;
759	    }
760	
761	    bool copy(ggml_backend_t backend, const ggml_tensor * src, ggml_tensor * dst, ggml_cgraph * graph) {
762	        const auto it = layer_of.find(src);
763	        if (it == layer_of.end()) {
764	            return false;
765	        }
766	        const int32_t il      = it->second.first;
767	        const bool    has_cpu = it->second.second;
768	        layer & l = layers[il];
769	        group & g = groups[l.ig];
770	
771	        GGML_ASSERT(backend == devices[g.id].backend);
772	
773	        // the get_rows that looks up the slots of the selected experts
774	        const int n_nodes = ggml_graph_n_nodes(graph);
775	        const ggml_tensor * lookup = nullptr;
776	        for (int i = 0; i < n_nodes && lookup == nullptr; ++i) {
777	            const ggml_tensor * node = ggml_graph_node(graph, i);
778	            if (node->op == GGML_OP_GET_ROWS && node->src[0] == dst) {
779	                lookup = node;
780	            }
781	        }
782	        GGML_ASSERT(lookup != nullptr);
783	
784	        // the selected experts must be computed in an earlier split
785	        // the scheduler starts a new split at the lookup because it reads a host weight, but only if the split already has inputs
786	        const ggml_tensor * sel = lookup->src[1];
787	        for (int i = 0; i < n_nodes; ++i) {
788	            const ggml_tensor * node = ggml_graph_node(graph, i);
789	            if (node == sel || node == sel->view_src) {
790	                GGML_ABORT("the experts of layer %d are selected in the same split as their MoE cache lookup", il);
791	            }
792	        }
793	        GGML_ASSERT(ggml_is_contiguous(sel));
794	        GGML_ASSERT(sel->op == GGML_OP_RESHAPE); // of the [n_expert_used, n_tokens] ids, see build_moe_cache_slots
795	
796	        const int32_t n_used = (int32_t) sel->src[0]->ne[0];
797	
798	        ids.resize(ggml_nelements(sel));
799	        ggml_backend_tensor_get_async(backend, sel, ids.data(), 0, ggml_nbytes(sel));
800	        ggml_backend_synchronize(backend);
801	
802	        if (trace != nullptr) {
803	            write_trace(il, n_used);
804	        }
805	
806	        // part of the misses is computed on the CPU once the cache is full, the carry keeps the share right on average
807	        const uint32_t share_q = has_cpu && g.lru.n_filled == g.lru.n_slots ? cpu_share_q : 0;
808	        auto n_cpu = [&](size_t n_miss) {
809	            const uint64_t acc = (uint64_t) n_miss*share_q + l.cpu_acc;
810	            l.cpu_acc = acc & 0xffff;
811	            return (size_t) (acc >> 16);
812	        };
813	        size_t n_hit = 0;
814	        if (!g.lru.plan(il, ids.data(), ids.size(), sel->src[0]->ne[1], n_used, n_zero, n_cpu, fills, cpu, n_hit)) {
815	            GGML_ABORT("the MoE cache is too small for the experts selected in layer %d", il);
816	        }
817	        if (has_cpu) {
818	            int32_t * cpu_map = (int32_t *) l.cpu_map->data;
819	            for (int32_t e : l.cpu_experts) {
820	                cpu_map[e] = -1;
821	            }
822	            l.cpu_experts.clear();
823	            for (const auto & f : cpu) {
824	                cpu_map[f.expert] = f.expert;
825	                l.cpu_experts.push_back(f.expert);
826	            }
827	        }
828	
829	        // upload the missing experts, consecutive experts going to consecutive slots are uploaded together
830	        size_t bytes = 0;
831	        for (size_t ip = 0; ip < l.experts.size(); ++ip) {
832	            const ggml_tensor * w    = l.experts[ip];
833	            ggml_tensor       * bank = g.banks[ip];
834	            const size_t expert_size = w->nb[2];
835	            for (size_t i = 0; i < fills.size();) {
836	                size_t n = 1;
837	                while (i + n < fills.size() && fills[i + n].expert == fills[i].expert + (int32_t) n && fills[i + n].slot == fills[i].slot + (int32_t) n) {
838	                    n++;
839	                }
840	                ggml_backend_tensor_set_async(backend, bank, (const uint8_t *) w->data + fills[i].expert*expert_size, fills[i].slot*expert_size, n*expert_size);
841	                bytes += n*expert_size;
842	                i += n;
843	            }
844	        }
845	
846	        stats & st = ids.size() <= (size_t) 8*n_expert_used ? stats_small : stats_large;
847	        st.hits   += n_hit;
848	        st.misses += fills.size() + cpu.size();
849	        st.cpu    += cpu.size();
850	        st.bytes  += bytes;
851	
852	        // the next copy synchronizes the backend before it changes the slot map again
853	        ggml_backend_tensor_set_async(backend, dst, l.slot_map->data, 0, ggml_nbytes(l.slot_map));
854	
855	        return true;
856	    }
857	
858	    void log_stats() const {
859	        auto log = [](const char * name, const stats & st) {
860	            const size_t n = st.hits + st.misses;
861	            if (n == 0) {
862	                return;
863	            }
864	            LLAMA_LOG_INFO("llama_moe_cache: %s: hits = %zu, misses = %zu (%zu on the CPU), hit rate = %.2f%%, uploaded = %.2f MiB\n",
865	                name, st.hits, st.misses, st.cpu, 100.0*st.hits/n, st.bytes/1024.0/1024.0);
866	        };
867	        log("ubatch <= 8", stats_small);
868	        log("ubatch  > 8", stats_large);
869	        if (stats_copy.hits > 0) {
870	            LLAMA_LOG_INFO("llama_moe_cache: large batches: %zu experts copied from the cache, %.2f MiB\n", stats_copy.hits, stats_copy.bytes/1024.0/1024.0);
871	        }
872	    }
873	};
